mapper.select:
SELECT t.id, t.mix_area, t.glue, p.stock_num, t.safe_stock, t.reserve_stock_rate, t.remark, t.del_flag, t.create_by, t.create_time, t.update_by, t.update_time FROM t_glue_safe_stock t LEFT JOIN (select MIX_AREA,GLUE,STOCK_DATE,DEL_FLAG,sum(ifnull( STOCK_NUM, 0 )) stock_num from (select MIX_AREA,GLUE,STOCK_DATE,DEL_FLAG,STOCK_NUM from T_ML_GLUE_STOCK union all select MIX_AREA,GLUE,STOCK_DATE,DEL_FLAG,STOCK_NUM from T_GLUE_STOCK) as s GROUP BY MIX_AREA, GLUE, STOCK_DATE, DEL_FLAG) p ON p.STOCK_DATE = #{todayDate,jdbcType=TIMESTAMP} AND p.DEL_FLAG = 0 AND t.GLUE = p.GLUE AND t.MIX_AREA = p.MIX_AREA WHERE t.del_flag = '0' and t.mix_area = #{mixArea} and INSTR(t.glue, #{glue}) > 0
order by create_time desc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType=VARCHAR} MIX_AREA, #{data.glue,jdbcType=VARCHAR} GLUE
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from T_GLUE_SAFE_STOCK m inner join temp_table t on m.MIX_AREA = t.MIX_AREA and m.GLUE = t.GLUE and m.del_flag ='0'

mapper.insert:
insert into t_glue_safe_stock (id,mix_area,glue,safe_stock,reserve_stock_rate,remark,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{glueSafeStock.mixArea,jdbcType=VARCHAR} mix_area, #{glueSafeStock.glue,jdbcType=VARCHAR} glue, #{glueSafeStock.safeStock,jdbcType=DOUBLE} safe_stock, #{glueSafeStock.reserveStockRate,jdbcType=DOUBLE} reserve_stock_rate, #{glueSafeStock.remark,jdbcType=VARCHAR} remark, #{glueSafeStock.delFlag,jdbcType=VARCHAR} del_flag, #{glueSafeStock.createBy,jdbcType=VARCHAR} create_by, #{glueSafeStock.createTime,jdbcType=TIMESTAMP} create_time, #{glueSafeStock.updateBy,jdbcType=VARCHAR} update_by, #{glueSafeStock.updateTime,jdbcType=TIMESTAMP} update_time
) x
